"""Valid synthetic Core snapshot, with identities generated by Core itself."""
from pathlib import Path
import json
import sys
import tempfile
sys.path[:0] = ['python', 'python/vendor']
from game_translation.project import index_entries
from game_translation.storage import stable_id
from storage import identity

count = int(sys.argv[1])
folder = Path(tempfile.mkdtemp(prefix=f'batch2-{count}-', dir='.test-output')).resolve()
work, game, data = folder/'work', folder/'game', folder/'state'
work.mkdir(); game.mkdir(); data.mkdir()
entries = [{'file': 'data/scenario/story.ks', 'path': str(i), 'type': 'dialogue', 'speaker': 'ミナ',
            'text': f'第{i}段、ミナは図書館で手紙を読んだ。The library is quiet.' + ('長い文章。'*50 if i%997==0 else ''),
            'scene': f'story.ks:*chapter_{i//140}', 'scene_title': f'story.ks:*chapter_{i//140}', 'scene_kind': 'script_label'} for i in range(count)]
tasks, scenes = index_entries(entries, 'tyrano')
for i, task in enumerate(tasks):
    task.update(translation=f'第{i}段，明天在图书馆读信。' + ('稀有标记' if i%9999==0 else ''), status='NEEDS_HUMAN', revision=1)
project_id = f'synthetic-batch2-{count}'
manifest = {'schema_version': 3, 'project_id': project_id, 'engine': {'family': 'tyrano'}, 'game_dir': str(game),
            'entries_hash': stable_id(entries), 'scenes': scenes}
(work/'project.json').write_text(json.dumps(manifest, ensure_ascii=False), encoding='utf-8')
(work/'entries.json').write_text(json.dumps(entries, ensure_ascii=False), encoding='utf-8')
(work/'tasks.jsonl').write_text(''.join(json.dumps(t, ensure_ascii=False)+'\n' for t in tasks), encoding='utf-8')
session_id = f'benchmark-{count}'
state = {'schema_version': 1, 'session_id': session_id, 'workspace': str(folder), 'version': 1,
         'binding': {'project_id': project_id, 'game_dir': str(game), 'work_dir': str(work), 'phase': 'project_ready'},
         'pending': None, 'notice': None, 'grants': []}
directory = data/'sessions'/identity(session_id); directory.mkdir(parents=True)
(directory/'binding.json').write_text(json.dumps(state), encoding='utf-8')
request = {'operation': 'search_query', 'context': {'sessionId': session_id, 'workspace': str(folder)},
           'config': {'dataDirectory': str(data), 'allowedGameRoots': [], 'allowedWorkRoots': []},
           'args': {'project_id': project_id, 'client_id': 'perf', 'diagnostics': True, 'query': {'fields': {'target': {'text': '明天'}}}}}
(folder/'request.json').write_text(json.dumps(request, ensure_ascii=False), encoding='utf-8')
print(str(folder))
